INSERT INTO "ntss"."sys_data_set" ("sql_cd", "sql", "db_class", "detail", "can_repeat", "use_application", "report_class", "memo", "reg_date", "up_date", "pre_sql_info") VALUES (220, 'SELECT  
  CONCAT(is_doubt, is_information, remarks, is_anesthesia, remarks_free) as remarks, --備考欄情報  
  insu_dr_id, --保険医ID  
  insu_dr_name, --保険医名称  
  insu_dr_sign, --保険医署名  
  anesthesiologist_license_no, --麻薬施用者番号  
  ord_prescription_no, --処方オーダー番号 
  insurance_cd --保険情報コード  
FROM (  
  SELECT  
    CASE WHEN is_doubt = ''1'' THEN ''【保険医療機関へ疑義照会の上で調剤】'' ELSE '''' END as is_doubt, --疑義照会  
    CASE WHEN is_information = ''1'' THEN ''【保険医療機関へ情報提供】'' ELSE '''' END as is_information, --情報提供  
    CASE WHEN is_anesthesia = ''1'' THEN ''【麻薬含む】'' ELSE '''' END as is_anesthesia, --麻薬処方フラグ  
    CASE WHEN remarks_free IS NOT NULL THEN CONCAT(''【'', personal_info_decrypt(remarks_free),''】'') ELSE '''' END as remarks_free, --保険医名称  
    (SELECT string_agg(DISTINCT ''【'' || trim(unnest_value) || ''】'', '''')  
     FROM unnest(string_to_array(opp.remarks, '','')) AS unnest_value) AS remarks, --備考欄情報  
    opp.insu_dr_id, --保険医ID  
    personal_info_decrypt(opp.insu_dr_name) as insu_dr_name, --保険医名称  
    personal_info_decrypt(opp.insu_dr_sign) as insu_dr_sign, --保険医署名  
    personal_info_decrypt(mpu.anesthesiologist_license_no) as anesthesiologist_license_no, --麻薬施用者番号  
    opp.ord_prescription_no, --処方オーダー番号
    opp.insurance_cd --保険情報コード 
  FROM  
    ord_personal_prescription opp  
  LEFT JOIN  
    mst_personal_user mpu ON opp.insu_dr_id = mpu.user_id AND mpu.is_del = ''0'' AND mpu.is_disp = ''1''  
  WHERE  
    opp.is_del = ''0'' AND opp.is_disp = ''1''  
    AND opp.ord_prescription_no = @ordPreNo  
) AS subquery', 3, '[{"preview": "なし", "can_calc": "0", "data_code": "remarks", "data_name": "備考欄情報", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "remarks", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "xxxxxx", "can_calc": "0", "data_code": "insu_dr_id", "data_name": "保険医ID", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_dr_id", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "日機装　太郎", "can_calc": "0", "data_code": "insu_dr_name", "data_name": "保険医名称", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_dr_name", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "日機装　太郎", "can_calc": "0", "data_code": "insu_dr_sign", "data_name": "保険医署名", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_dr_sign", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "xxxxxxxx", "can_calc": "0", "data_code": "anesthesiologist_license_no", "data_name": "麻薬施用者番号", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "anesthesiologist_license_no", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}]', '0', '{"applications": [1]}', '{"classes": [1, 2, 9]}', '処方(最新)：@facilityCd @patId  使用', '2024-04-19 10:24:31.73', CURRENT_TIMESTAMP, '[{"sql_cd": 223, "field_name": "ord_prescription_no", "replace_var": "@ordPreNo"}]');
